    def _init_close_button_hover(self):
        """Кнопка закрытия по умолчанию спрятана за правым краем окна и
        выезжает наружу, когда курсор оказывается у верхнего правого угла."""
        self._close_hidden_geo = QtCore.QRect(900, 0, 25, 25)  # полностью за краем окна
        self._close_shown_geo = QtCore.QRect(875, 0, 25, 25)   # выехавшее положение
        self.pushButton_close.setGeometry(self._close_hidden_geo)

        self._close_anim = QtCore.QPropertyAnimation(self.pushButton_close, b"geometry")
        self._close_anim.setDuration(150)
        self._close_anim.setEasingCurve(QtCore.QEasingCurve.Type.OutCubic)

        self._close_visible = False
        # Наведение проверяем таймером, а не enterEvent/leaveEvent — так надёжнее,
        # потому что кнопка и полоска для драга перекрываются другими виджетами
        # (QTabWidget поверх всего окна), и события мыши могут не доходить.
        self._close_hover_zone = 40  # ширина/высота зоны у угла в пикселях
        self._hover_timer = QtCore.QTimer(self.centralwidget)
        self._hover_timer.setInterval(60)
        self._hover_timer.timeout.connect(self._check_close_hover)
        self._hover_timer.start()

    def _check_close_hover(self):
        pos = self.centralwidget.mapFromGlobal(QtGui.QCursor.pos())
        zone = self._close_hover_zone
        near_edge = (
            self.centralwidget.rect().contains(pos)
            and pos.x() >= self.centralwidget.width() - zone
            and pos.y() <= zone
        )
        if near_edge == self._close_visible:
            return
        self._close_visible = near_edge
        target = self._close_shown_geo if near_edge else self._close_hidden_geo
        self._close_anim.stop()
        self._close_anim.setStartValue(self.pushButton_close.geometry())
        self._close_anim.setEndValue(target)
        self._close_anim.start()

